<script setup>
import {computed,ref,watch} from 'vue';
const props=defineProps({columns:Array,rows:Array,calc:Object,searchable:{type:Boolean,default:true},what:{type:String,default:'rows'},sortBy:String,limit:{type:Number,default:250},clickable:Boolean});
const emit=defineEmits(['open']);
const query=ref(''),sort=ref(props.sortBy||''),direction=ref(-1),shown=ref(props.limit);
const numeric=c=>['amt','int','pct'].includes(c.t),value=(c,r)=>c.v?c.v(r):r[c.k];
const format=(c,v)=>c.t==='amt'?props.calc.fmt(v):c.t==='pct'?Number(v||0).toFixed(1)+'%':c.t==='int'?Number(v||0).toLocaleString('en-IN'):c.t==='date'?props.calc.dmy(v):Array.isArray(v)?v.join(', '):v??'';
const filtered=computed(()=>{
 const rows=props.rows.filter(r=>!query.value||props.columns.some(c=>c.search!==false&&String(value(c,r)??'').toLowerCase().includes(query.value.toLowerCase())));
 const c=props.columns.find(c=>c.k===sort.value);return c?rows.slice().sort((a,b)=>direction.value*(numeric(c)?props.calc.num(value(c,a))-props.calc.num(value(c,b)):String(value(c,a)||'').localeCompare(String(value(c,b)||''),undefined,{numeric:true,sensitivity:'base'}))):rows;
});
const visible=computed(()=>filtered.value.slice(0,shown.value));
watch(query,()=>shown.value=props.limit);
function order(c){if(c.nosort)return;if(sort.value===c.k)direction.value*=-1;else{sort.value=c.k;direction.value=numeric(c)?-1:1;}}
const classes=(c,r)=>[numeric(c)?'n':'',c.stick?'stick':'',typeof c.cls==='function'?c.cls(r):c.cls];
const total=c=>c.sumFn?c.sumFn(filtered.value):format(c,filtered.value.reduce((s,r)=>s+props.calc.num(value(c,r)),0));
</script>
<template><div><div v-if="searchable" class="esr-tbar"><input v-model="query" class="esr-tsearch" type="search" :placeholder="'🔍 Search '+what+'…'"><span class="esr-tcount">{{query?filtered.length+' of ':''}}{{rows.length.toLocaleString('en-IN')}} {{what}}</span></div><div class="esr-tblwrap"><table class="esr-table"><thead><tr><th v-for="c in columns" :key="c.k" :class="[numeric(c)?'n':'',c.nosort?'':'sort',sort===c.k?'active':'',c.stick?'stick':'']" :title="c.tip" :data-k="c.k" @click="order(c)">{{c.l}}<span v-if="!c.nosort" class="ar">{{sort===c.k?(direction>0?'▲':'▼'):'⇅'}}</span></th></tr></thead><tbody><tr v-for="(row,i) in visible" :key="row.key||row.invoice||row.name||i" :class="{click:clickable}" :data-i="i" @click="clickable&&emit('open',row)"><td v-for="c in columns" :key="c.k" :class="classes(c,row)"><a v-if="c.k==='invoice'" class="esr-link" :href="'/app/sales-invoice/'+encodeURIComponent(row.invoice)" target="_blank" rel="noopener" @click.stop>{{row.invoice}}</a><span v-else-if="c.k==='rank'" class="esr-rank" :class="row.rank<=3?'r'+row.rank:''">{{row.rank}}</span><strong v-else-if="c.k==='name'">{{value(c,row)}}</strong><span v-else-if="['id','refId','incId'].includes(c.k)" class="esr-id">{{value(c,row)}}</span><span v-else-if="['topCat','topBk'].includes(c.k)" class="esr-pill" :class="c.k==='topCat'?'p-teal':''">{{value(c,row)}}</span><template v-else>{{format(c,value(c,row))}}</template></td></tr><tr v-if="!visible.length"><td :colspan="columns.length"><div class="esr-empty">{{rows.length?'No rows match the search.':'No data for the selected filters.'}}</div></td></tr></tbody><tfoot v-if="filtered.length"><tr><td v-for="(c,i) in columns" :key="c.k" :class="[numeric(c)?'n':'',c.stick?'stick':'']">{{c.sum||c.sumFn?total(c):i===0?'Total ('+filtered.length.toLocaleString('en-IN')+')':''}}</td></tr></tfoot></table></div><div v-if="filtered.length>visible.length" class="esr-more">Showing {{visible.length}} of {{filtered.length}} &nbsp;<button type="button" class="esr-btn esr-btn-xs" @click="shown+=250">Show 250 more</button> <button type="button" class="esr-btn esr-btn-xs" @click="shown=Infinity">Show all</button></div></div></template>
